use std :: time :: Duration ; use schemars :: JsonSchema ; use serde :: { Deserialize , Serialize } ; use crate :: { ModelId , ProviderId } ; # [doc = " The result of testing a single model."] # [doc = ""] # [doc = " Contains timing information, success/failure status, and a composite score"] # [doc = " that can be used to rank models."] # [derive (Debug , Clone , Serialize , Deserialize , JsonSchema , PartialEq)] pub struct ModelTestResult { # [doc = " The provider that hosts this model."] pub provider_id : ProviderId , # [doc = " The model that was tested."] pub model_id : ModelId , # [doc = " Whether the model responded successfully."] pub success : bool , # [doc = " Time to first token (TTFT) — how long until the first response chunk"] # [doc = " arrived."] pub time_to_first_token : Option < Duration > , # [doc = " Total elapsed time for the test request."] pub total_duration : Option < Duration > , # [doc = " Composite score (0.0–1.0) combining speed, success, and capability"] # [doc = " signals. Higher is better."] pub score : f64 , # [doc = " Error message if the test failed."] pub error : Option < String > , }